import { integer, sqliteTable, text } from 'drizzle-orm/sqlite-core';

// The organisation's synced tables. Every synced table has a single text
// primary key `id`, so the change log and the client undo log can name a row
// by (table, id). Ids are generated by the caller (client), never by SQLite.

export const songs = sqliteTable('songs', {
  id: text('id').primaryKey(),
  title: text('title').notNull(),
});

// A label's id is derived from its normalised text (see labelId), so two
// devices that create "Bridge" offline create the same row (SYNC-A12).
export const labels = sqliteTable('labels', {
  id: text('id').primaryKey(),
  name: text('name').notNull(),
});

export const songLabels = sqliteTable('song_labels', {
  id: text('id').primaryKey(), // `${songId}|${labelId}`
  songId: text('song_id').notNull().references(() => songs.id),
  labelId: text('label_id').notNull().references(() => labels.id),
});

export const presentations = sqliteTable('presentations', {
  id: text('id').primaryKey(),
  name: text('name').notNull(),
  // Set when the presentation is in the server trash (D14).
  deletedAt: integer('deleted_at'),
});

export const presentationItems = sqliteTable('presentation_items', {
  id: text('id').primaryKey(),
  presentationId: text('presentation_id').notNull().references(() => presentations.id),
  songId: text('song_id').notNull().references(() => songs.id),
  sort: integer('sort').notNull(),
});

export const schema = { songs, labels, songLabels, presentations, presentationItems };

/** Synced tables in parent-before-child order. */
export const syncedTables = [songs, labels, songLabels, presentations, presentationItems];

/** Bumped whenever a synced table changes shape; part of the pull cookie's scope. */
export const SCHEMA_VERSION = 1;

// Hand-written DDL for the spike. The real package would generate this with
// drizzle-kit migrations; the columns must match the Drizzle tables above.
export const orgDdl: string[] = [
  `CREATE TABLE IF NOT EXISTS songs (id TEXT PRIMARY KEY NOT NULL, title TEXT NOT NULL)`,
  `CREATE TABLE IF NOT EXISTS labels (id TEXT PRIMARY KEY NOT NULL, name TEXT NOT NULL)`,
  `CREATE TABLE IF NOT EXISTS song_labels (id TEXT PRIMARY KEY NOT NULL,
     song_id TEXT NOT NULL REFERENCES songs(id), label_id TEXT NOT NULL REFERENCES labels(id))`,
  `CREATE TABLE IF NOT EXISTS presentations (id TEXT PRIMARY KEY NOT NULL, name TEXT NOT NULL, deleted_at INTEGER)`,
  `CREATE TABLE IF NOT EXISTS presentation_items (id TEXT PRIMARY KEY NOT NULL,
     presentation_id TEXT NOT NULL REFERENCES presentations(id),
     song_id TEXT NOT NULL REFERENCES songs(id), sort INTEGER NOT NULL)`,
];
